mapper.select:
/* Staff.findStaffList */
select
	row_number() over() as num, 
	a.*
from (
	select *
	from staff
	where 1=1
	
	and (
		id like concat('%', #{searchText}, '%')
		or staff_name like concat('%', #{searchText}, '%')
		or phone_number like concat('%', #{searchText}, '%')
	)
	
	
	order by 
		
			
				id ${orderType}
			
			
				staff_name ${orderType}
			
			
				id desc
			
		
	
	limit #{firstIndex}, #{recordCountPerPage}
) a

/* Staff.getStaffInfo */
select
	staff_id
	, staff_name
from staff
where staff_id = #{staffId}
and password = #{password}
